"""Bounded equal-rise crown on an attached Bundle's conforming XY charts.

Original curb segments supply physical fibres. Beyond a curb's independent
terminal station its terminal segment is extended linearly, never clamped to
a constant point. This branch accepts that extension only when the resulting
field reproduces every original mouth/outer-boundary height. It is a height
construction primitive; network grade and seam-normal checks remain external.
All input coordinates and the Reference table use unexaggerated physical Z.
"""
import bpy
from .path_surface_nodes import _Nodes
from . import aggregate_bundle_gap_nodes as gaps
from . import boundary_quad_bridge_nodes as bridge
from . import bundle_crown_nodes as crown

NAME = 'Prochitecture Streets / Attached Bundle bounded height v1'
HEIGHT_TOLERANCE = 1e-7


def _query_extended(g, wire, station):
    geometry, count, first, last, _, query = wire
    position = g.node('GeometryNodeInputPosition', 'Original physical curb position').outputs[0]
    metric = g.named('_bridge_metric', 'FLOAT')
    extensions = []
    for a, b, s in ((0, 1, first), (g.math('SUBTRACT', count, 1.), g.math('SUBTRACT', count, 2.), last)):
        pa, pb = [g.sample(geometry, position, index, 'FLOAT_VECTOR') for index in (a, b)]
        step = g.math('SUBTRACT', g.sample(geometry, metric, b, 'FLOAT'), s)
        extensions.append(bridge._mix(g, pa, pb, g.math('DIVIDE', g.math('SUBTRACT', station, s), step)))
    result = g.switch(g.compare(station, first, 'LESS_THAN'), query(station), extensions[0], 'VECTOR')
    return g.switch(g.compare(station, last, 'GREATER_THAN'), result, extensions[1], 'VECTOR')


def build():
    if NAME in bpy.data.node_groups: return bpy.data.node_groups[NAME]
    tree = bpy.data.node_groups.new(NAME, 'GeometryNodeTree'); g = _Nodes(tree)
    for key in ('Geometry', 'Reference', *gaps.SIDES, 'Head', 'Tail'):
        tree.interface.new_socket(name=key, in_out='INPUT', socket_type='NodeSocketGeometry')
    for key, default in (('Datum', 0.), ('Rise', .08), ('Height Exaggeration', 1.)):
        tree.interface.new_socket(name=key, in_out='INPUT', socket_type='NodeSocketFloat').default_value = default
    tree.interface.new_socket(name='Original Count', in_out='INPUT', socket_type='NodeSocketInt')
    for key in ('Geometry', 'Reference', 'Diagnostics'):
        tree.interface.new_socket(name=key, in_out='OUTPUT', socket_type='NodeSocketGeometry')
    tree.interface.new_socket(name='Valid', in_out='OUTPUT', socket_type='NodeSocketBool')
    inp = g.node('NodeGroupInput', 'Conforming XY chart and unchanged physical boundaries')
    out = g.node('NodeGroupOutput', 'One bounded crown; independent physical seams checked')
    frame = g.node('GeometryNodeGroup', 'Original four-curb coordinate frame'); frame.node_tree = gaps.build()
    for key in (*gaps.SIDES, 'Head'): g.set(inp.outputs[key], frame.inputs[key])
    axis, origin, lateral = [frame.outputs[key] for key in ('Axis', 'Origin', 'Lateral')]
    pos = g.node('GeometryNodeInputPosition', 'Physical XY query').outputs[0]
    index = g.node('GeometryNodeInputIndex', 'Physical reference index').outputs[0]
    station = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', pos, origin), axis)
    wires = [bridge._wire(g, inp.outputs[key], axis, at, origin, shared=True) for at, key in enumerate(gaps.SIDES)]
    values = [_query_extended(g, wire, station) for wire in wires]
    a, b, span = [g.vector('DOT_PRODUCT', g.vector('SUBTRACT', v, values[0]), lateral) for v in values[1:]]
    coordinate = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', pos, values[0]), lateral)
    law = g.node('GeometryNodeGroup', 'Shared squared-shoulder crown law'); law.node_tree = crown.build()
    for key, value in (('Coordinate', coordinate), ('Left Shoulder', a), ('Right Start', b), ('Span', span),
                       ('Datum', inp.outputs['Datum']), ('Rise', inp.outputs['Rise'])):
        g.set(value, law.inputs[key])
    predicted = law.outputs['Height']; z = g.component(pos, 'Z')
    perimeter = bridge._join(g, *(inp.outputs[key] for key in ('Side A', 'Side B', 'Head', 'Tail')))
    error = g.math('ABSOLUTE', g.math('SUBTRACT', predicted, z))
    boundary_error = g.stat(perimeter, error, output='Max')
    ceiling = g.math('ADD', inp.outputs['Datum'], inp.outputs['Rise'])
    checks = [frame.outputs['Valid'], *[wire[4] for wire in wires],
        g.compare(inp.outputs['Height Exaggeration'], 0., 'GREATER_EQUAL'),
        g.compare(bridge._size(g, inp.outputs['Geometry'], 'Face Count'), 0, 'GREATER_THAN'),
        g.stat(perimeter, law.outputs['Valid']), g.stat(inp.outputs['Geometry'], law.outputs['Valid']),
        g.compare(boundary_error, HEIGHT_TOLERANCE, 'LESS_EQUAL')]
    for key, expected in (('Side A', inp.outputs['Datum']), ('Side B', inp.outputs['Datum']),
                          ('Inner A', ceiling), ('Inner B', ceiling)):
        checks.append(g.compare(g.stat(inp.outputs[key], g.math('ABSOLUTE', g.math('SUBTRACT', z, expected)),
            output='Max'), HEIGHT_TOLERANCE, 'LESS_EQUAL'))
    key = g.named('_bridge_key', 'FLOAT_VECTOR')
    pin = g.compare(g.component(key, 'X'), 0.)
    key_exists = g.node('GeometryNodeInputNamedAttribute', 'Surface identity must exist'); key_exists.data_type = 'FLOAT_VECTOR'
    key_exists.inputs['Name'].default_value = '_bridge_key'
    checks.append(g.stat(inp.outputs['Geometry'], key_exists.outputs['Exists']))
    # Newly constructed internal reference points have no authored physical
    # height. Evaluate the crown there, instead of retaining a rounded cap Z
    # or assigning the exact maximum to collinear samples off the peak line.
    # Every existing source vertex keeps its complete original XYZ unchanged.
    old_reference = g.compare(index, inp.outputs['Original Count'], 'LESS_THAN')
    reference = bridge._position(g, inp.outputs['Reference'],
        g.xyz(g.component(pos, 'X'), g.component(pos, 'Y'), g.switch(old_reference, predicted, z)))
    original = g.sample(reference, pos, g.component(key, 'Y'), 'FLOAT_VECTOR')
    reference_count = bridge._size(g, inp.outputs['Reference'])
    checks.extend((g.compare(inp.outputs['Original Count'], 0, 'GREATER_THAN', 'INT'),
        g.compare(inp.outputs['Original Count'], reference_count, 'LESS_EQUAL', 'INT')))
    reference_ok = g.all(g.compare(g.component(key, 'Y'), 0., 'GREATER_EQUAL'),
        g.compare(g.component(key, 'Y'), reference_count, 'LESS_THAN'),
        g.compare(g.vector('DISTANCE', g.xyz(g.component(original, 'X'), g.component(original, 'Y')),
            g.xyz(g.component(pos, 'X'), g.component(pos, 'Y'))), bridge.TOLERANCE, 'LESS_EQUAL'))
    checks.append(g.stat(inp.outputs['Geometry'], g.either(g.boolean('NOT', pin), reference_ok)))
    physical_z = g.component(original, 'Z')
    pin_error = g.stat(inp.outputs['Geometry'], g.switch(pin, 0.,
        g.math('ABSOLUTE', g.math('SUBTRACT', predicted, physical_z))), output='Max')
    checks.append(g.compare(pin_error, HEIGHT_TOLERANCE, 'LESS_EQUAL'))
    height = g.switch(pin, predicted, physical_z)
    mesh = g.store(inp.outputs['Geometry'], 'st_cn_height', height)
    checks.append(g.stat(mesh, g.all(g.compare(g.named('st_cn_height', 'FLOAT'), inp.outputs['Datum'], 'GREATER_EQUAL'),
        g.compare(g.named('st_cn_height', 'FLOAT'), ceiling, 'LESS_EQUAL'))))
    mesh = bridge._position(g, mesh, g.xyz(g.component(pos, 'X'), g.component(pos, 'Y'),
        g.math('ADD', inp.outputs['Datum'], g.math('MULTIPLY', inp.outputs['Height Exaggeration'],
            g.math('SUBTRACT', g.named('st_cn_height', 'FLOAT'), inp.outputs['Datum'])))))
    valid = g.all(*checks)
    diagnostic = gaps._line(g, 1)
    for suffix, value, kind in (
            ('valid', valid, 'BOOLEAN'), ('boundary_error', boundary_error, 'FLOAT'),
            ('pin_error', pin_error, 'FLOAT'), ('minimum', g.stat(mesh, g.named('st_cn_height', 'FLOAT')), 'FLOAT'),
            ('maximum', g.stat(mesh, g.named('st_cn_height', 'FLOAT'), output='Max'), 'FLOAT')):
        diagnostic = g.store(diagnostic, 'st_bu_height_'+suffix, value, kind)
    g.set(g.switch(valid, None, mesh, 'GEOMETRY'), out.inputs['Geometry'])
    g.set(g.switch(valid, None, reference, 'GEOMETRY'), out.inputs['Reference'])
    g.set(diagnostic, out.inputs['Diagnostics']); g.set(valid, out.inputs['Valid'])
    tree['st_height_construction_only'] = True
    return tree
